  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
}
.hotswap.avatars_inline::-webkit-scrollbar {
  display: none;
}
.hotswap.avatars_inline {
  scrollbar-width: none;
}

@media (max-width: 768px) {
  .hotswap.avatars_inline {
    overflow: auto;
  }
}
